import json,pathlib
R=json.load(open('final_results.json'));H=json.load(open('refined_harmonic_results.json'));D=json.load(open('final_diagnostics.json'))
units_intro='Physical units were not supplied. Here Y, V and U mean the recorded units of `y`, `x1` and `x2`; time is in seconds. The observed kinematic relation makes V consistent with Y/s. Trigonometric arguments use the raw numerical coordinate `y`; an angle interpretation is assumed only as a useful mathematical analogy, not identified physical provenance. '
method_common='Deterministic bounded nonlinear least squares with scipy.optimize.least_squares, method trf (trust-region reflective), x_scale jac, finite-difference Jacobian and linear loss. All coefficients in this candidate were optimized jointly, without resetting states after the initial measured state of each trajectory. RK4 used `T_s = 0.01` s and held the logged `x2` constant during a step, matching the stated scoring protocol. This output-error method was chosen over derivative-only regression because finite-difference derivative targets are quantized and scoring concerns free-running `y`. There are no random seeds. '
data_text='Final estimation used every row of data/train.csv (all thirteen trajectories) and data/val.csv (all three trajectories); first states initialize simulations but first rows do not contribute residuals. Validation trajectories were first used separately for structure comparison, then included in the final parameter refit to use all available information. Consequently the final reported validation error is an in-sample diagnostic, not an unbiased holdout estimate. Trajectories remain separate experiments. '
criterion='Unweighted sum of squared free-running errors in `y` over all noninitial samples, with equal weight per sample, rather than equal weight per trajectory. This matches the task scoring aggregation. `dx1` informed preliminary derivative-regression screening and residual diagnostics, but is not included in the final objective. '
refs='Related dry-friction simulation reference cited from memory, not independently verified: D. Karnopp, Computer Simulation of Stick-Slip Friction in Mechanical Dynamic Systems, ASME Journal of Dynamic Systems, Measurement, and Control (1985). This is a family-level reference, not a claim that the expression is Karnopp\'s exact algorithm. SciPy documentation retrieval was attempted but returned no usable text; software settings below report the actual calls, not an externally verified quotation. '
def starts(names,p):return ', '.join('`'+n+' = '+format(v,'.17g')+'`' for n,v in zip(names,p))
def bounds(names,r):return '; '.join('`'+format(lo,'.8g')+' <= '+n+' <= '+format(hi,'.8g')+'`' for n,lo,hi in zip(names,*r['bounds']))
models=[('HarmonicFriction','harmonic',H,['b','k','c','f','g','s','h','j','l','m']),('BoundedStiction','projection',R['projection'],['b','k','c','f','g','tau','h','j','l','m']),('QuinticOscillator','polynomial',R['polynomial'],['b','k','c','f','g','s','a3','a5'])]
for label,form,r,names in models:
 p=r['p'];projection=form=='projection';poly=form=='polynomial'
 F='b + k*sin(y) + c*x1 + g*x2 + l*(cos(y)-1) + m*sin(2*y)'
 FF='f + h*sin(y) + j*(cos(y)-1)'
 if poly:expr='b + k*y + a3*y**3 + a5*y**5 + c*x1 + g*x2 - f*tanh(x1/s)'
 elif projection:expr='('+F+') - Min(('+FF+'), Max(-('+FF+'), ('+F+') + x1/tau))'
 else:expr=F+' - ('+FF+')*tanh(x1/s)'
 descriptions={'b':'constant acceleration offset','k':'coefficient of `y`' if poly else 'fundamental restoring-force coefficient multiplying `sin(y)`','c':'linear velocity damping coefficient multiplying `x1`','f':'baseline magnitude of the bounded velocity-opposing term','g':'linear logged-input gain multiplying `x2`','s':'velocity scale in `tanh(x1/s)`','tau':'relaxation time in the bounded-force projection; inside its unsaturated region the expression reduces to `-x1/tau`','h':'coefficient of `sin(y)` in the position-dependent friction bound','j':'coefficient of `cos(y)-1` in the position-dependent friction bound','l':'coefficient of the even restoring correction `cos(y)-1`','m':'coefficient of the second harmonic restoring correction `sin(2*y)`','a3':'cubic restoring coefficient multiplying `y**3`','a5':'quintic restoring coefficient multiplying `y**5`'}
 units={n:'V/s' for n in names};units.update(c='1/s',g='V/(s*U)',s='V',tau='s')
 if poly:units.update(k='V/(s*Y)',a3='V/(s*Y**3)',a5='V/(s*Y**5)')
 params=[{'name':n,'value':float(v),'unit':units[n],'type':'fitted','description':descriptions[n]+'. Units use the recorded-unit convention defined in discussion.'} for n,v in zip(names,p)]
 if form=='harmonic':
  initial=R['harmonic'];method=method_common+'First the joint train-plus-validation fit started at '+starts(names,initial['initial'])+'. It used max_nfev 100, ftol 1e-8 and diff_step 1e-4, ending at its evaluation limit. These starts came from the preliminary training-only state-dependent-friction harmonic fit in fit_statefriction.py. A refinement then started at '+starts(names,r['initial'])+' with max_nfev 70, ftol 1e-9 and diff_step 1e-6. It also ended at its evaluation limit; no convergence claim is made. The refinement changes the objective only slightly. '
 else:method=method_common+'Starting values were '+starts(names,r['initial'])+'. They were taken from the preliminary training-only '+('state-dependent bounded-friction harmonic fit in fit_statefriction.py' if projection else 'quintic smooth-friction fit in fit_rollout.py')+' to initialize near a stable trajectory solution. All parameters were then jointly refitted with max_nfev 100, ftol 1e-8 and diff_step 1e-4. The final solver reported successful termination. '
 method+='Starting values and bounds use each parameter\'s unit from the parameter table. The bounds were '+bounds(names,r)+'. Broad coefficient bounds constrain finite fits; restoring and damping signs encode the observed oscillator-like decay. The positive friction and smoothing bounds avoid sign-reversed dissipation and excessively stiff near-zero-velocity dynamics under the prescribed one-step RK4. Bounds are modeling assumptions, not known system limits. '
 diag=D[form];report='Final free-running `y` RMSE was `'+format(diag['train']['y_rmse'],'.6g')+'` Y on training and `'+format(diag['val']['y_rmse'],'.6g')+'` Y on the reused validation data. Derivative-residual RMSE was `'+format(diag['train']['dx1_rmse'],'.6g')+'` V/s and `'+format(diag['val']['dx1_rmse'],'.6g')+'` V/s, respectively; within-trajectory lag-one derivative-residual correlations were `'+format(diag['train']['residual_lag1'],'.4g')+'` and `'+format(diag['val']['residual_lag1'],'.4g')+'`. These nonwhite residuals leave quantization, unmodeled dynamics and input timing effects unresolved. '
 common_origin='Before fitting, affine, sparse polynomial, saturation, and state-dependent damping families were proposed. Exploratory ordinary least squares and nonlinear least squares in helper_nonlinear.py screened affine, sine, cubic, higher-polynomial, Coulomb, drag, input-nonlinearity and cross-term libraries; scan_terms.py also used sklearn.linear_model.ARDRegression as a diagnostic library screen, not as the final estimator. Centered differences showed `dy = x1` within numerical precision, so `dy` was fixed to `x1` without a fitted scale. The affine family and purely viscous damping had substantially worse free-running errors and were not delivered. Velocity-bin residuals and stopped trajectories motivated dry-friction-like terms; moving-row residual improvements from `sin(y)*sign(x1)` and `cos(y)*sign(x1)` motivated position dependence of its magnitude. No physical system description was available. '
 if poly:
  family='Quintic polynomial nonlinear oscillator, an extension of the Duffing oscillator, with smooth Coulomb-like damping. The Duffing family is named as an established model family; the extension here is empirical. '+refs
  interp=units_intro+'`dy = x1` is the kinematic relation. In `dx1`, `b` shifts acceleration, `k*y` supplies local linear restoring behavior, `a3*y**3` softens that behavior at intermediate amplitude, and the negative fitted `a5*y**5` restores an inward highest-order force at large amplitude. `c*x1` is linear damping, `g*x2` is input forcing, and `-f*tanh(x1/s)` is a smooth velocity-opposing force with bounded magnitude. These are mathematical effects; no masses, lengths or material properties are inferred. '
  origin=common_origin+'The cubic branch improved amplitude dependence over the affine model. The quintic term was added to approximate the sine-like softening over observed excursions while avoiding the outward highest-degree force of an unconstrained softening cubic model. Constant friction was retained to give an independently defensible compact polynomial alternative, not a coefficient perturbation of the harmonic model. Powers came from a manually enumerated polynomial library, not a genetic-programming search. '
  limit='Polynomial extrapolation is not a physical law and becomes very steep outside observed excursions. Smooth friction does not admit an exact interval of stuck equilibria. Its training-only held-out validation `y` RMSE before refitting was `0.0837067` Y. '
 elif projection:
  family='Nonlinear Fourier oscillator with a bounded-force projection regularization of dry friction and stiction. '+refs
  interp=units_intro+'`dy = x1` is the kinematic relation. The unconstrained force is `b + k*sin(y) + c*x1 + g*x2 + l*(cos(y)-1) + m*sin(2*y)`: `b` shifts acceleration, `k*sin(y)` is periodic restoring behavior, `c*x1` is linear damping, `g*x2` is input forcing, `l*(cos(y)-1)` adds an even correction vanishing at the origin, and `m*sin(2*y)` adds a second harmonic. The friction bound is `f + h*sin(y) + j*(cos(y)-1)`; `h` gives odd and `j` even position modulation. Clipping the trial force plus `x1/tau` to that bound gives exact relaxation `-x1/tau` when unsaturated, and force-minus-bounded-friction when saturated. Thus states at `x1 = 0` can remain stopped for a range of `y` and `x2`. The fitted bound remains positive for every real numerical `y`. '
  origin=common_origin+'The `Min` and `Max` projection was introduced after observing different nonzero stopping positions, which smooth friction drifts away from. It is a guessed regularization of set-valued Coulomb friction, not a known apparatus mechanism. Even and second-harmonic restoring corrections came from a manually enumerated trigonometric library after amplitude- and sign-dependent trajectory errors remained. '+ 'The clipped structure was selected for its stopping behavior, not because its held-out output error beat all smooth models. '
  limit='The projection is nonsmooth at saturation boundaries, so fitted `tau` is sensitive to the specified integration step; it is near its lower bound and should not be treated as a resolved physical time constant. Its training-only held-out validation `y` RMSE before refitting was `0.0828222` Y. '
 else:
  family='Nonlinear Fourier oscillator with state-dependent smooth Coulomb-like friction. '+refs
  interp=units_intro+'`dy = x1` is the kinematic relation. `b` shifts acceleration; `k*sin(y)` supplies periodic restoring behavior; `l*(cos(y)-1)` adds an even correction vanishing at the origin; `m*sin(2*y)` changes amplitude dependence via a second harmonic; `c*x1` provides linear damping; and `g*x2` supplies input forcing. `-(f + h*sin(y) + j*(cos(y)-1))*tanh(x1/s)` opposes velocity, with odd and even position modulation of its magnitude. The fitted magnitude stays positive for every real numerical `y`. The smooth transition scale is `s`. These are mathematical roles, not identified physical components. '
  origin=common_origin+'Even and second-harmonic restoring corrections were introduced after asymmetric free-running errors persisted in a sine-only oscillator. Trigonometric operators were motivated by the oscillator analogy and the raw coordinate range; candidate terms were manually enumerated and compared, not produced by genetic programming. Input cubic, quadratic, sign and saturation terms were also screened; a final input-nonlinearity trial produced only a small reused-validation improvement with additional complexity, so the linear input term was retained. '
  limit='`s` is at its lower fitting bound and is not a precisely identified physical friction width. Smooth friction permits slow drift rather than exact sticking, which contributes to errors on short decays. Its training-only held-out validation `y` RMSE before refitting was `0.0763671` Y. '
 limitations=limit+report+'No intended use, physical units, sensor accuracy, actuator dynamics, or true derivative measurements were supplied. The recorded derivatives are centered finite differences, not independent evidence. Models were checked only on supplied trajectories: training `-2.51328 <= y <= 2.53527` Y, `-20.1062 <= x1 <= 14.4514` V and `-4.94511 <= x2 <= 3.95251` U. Validation extends neither position nor velocity range substantially. Constant-input forcing far outside these data, alternate input timing, other integration steps, and long-term extrapolation are not validated. The state trajectories stayed finite and within the task bounds on supplied data, but no test score is known.'
 obj={'expressions':{'dy':'x1','dx1':expr},'parameters':params,'estimation':{'criterion':criterion,'data':data_text,'method':method,'script':'reproduce_candidates.py'},'discussion':{'family':family,'interpretation':interp,'origin':origin,'limitations':limitations}}
 pathlib.Path('models').mkdir(exist_ok=True);json.dump(obj,open('models/'+label+'.json','w'),indent=2)
json.dump({'order':['HarmonicFriction','BoundedStiction','QuinticOscillator'],'recommended':'HarmonicFriction','reason':'Recommended for its smooth closed form, position-dependent dissipative term and best pre-refit held-out validation output error among these delivered structures (`0.0763671` in recorded `y` units). After all-data refitting its training and reused-validation free-running errors are `0.0344979` and `0.0718753` in recorded `y` units. These final figures are no longer independent holdout evidence. BoundedStiction offers exact stopping behavior; QuinticOscillator provides a polynomial restoring alternative. No test data were accessed.'},open('models/pool.json','w'),indent=2)
# Standalone reproducer uses original fitting routines and archived starts, but no preliminary fit loops.
core=open('refit_final.py').read().split('R=json.load')[0]
core=core.replace("exec(open('fit_rollout.py').read().split('forms=')[0])",open('fit_rollout.py').read().split('forms=')[0])
tail='''\nimport sys\nlabel=sys.argv[1] if len(sys.argv)>1 else 'HarmonicFriction'\nmapping={'HarmonicFriction':'harmonic','BoundedStiction':'projection','QuinticOscillator':'polynomial'}\nform=mapping[label];r=json.load(open('final_results.json'))[form]\nopt=least_squares(lambda p:rollout(p,form,ALL),r['initial'],bounds=tuple(r['bounds']),x_scale='jac',max_nfev=100,ftol=1e-8,diff_step=1e-4)\nif form=='harmonic':\n opt=least_squares(lambda p:rollout(p,form,ALL),opt.x,bounds=tuple(r['bounds']),x_scale='jac',max_nfev=70,ftol=1e-9,diff_step=1e-6)\nprint(label,opt.x,metrics(opt.x,form,TR),metrics(opt.x,form,VA))\njson.dump({'label':label,'p':opt.x.tolist(),'train':metrics(opt.x,form,TR),'val':metrics(opt.x,form,VA)},open('reproduced_'+label+'.json','w'),indent=2)\n'''
open('reproduce_candidates.py','w').write(core+tail)
